"node -e '
async function main() {
  const pages = await fetch("http://192.168.1.15:9998/json").then(r => r.json());
  const pocPage = pages.find(p => p.url && p.url.includes("com.cinejoy.poc"));
  console.log("PoC Page:", pocPage ? pocPage.title : "Not found");
  if (!pocPage) return;

  const ws = new WebSocket(pocPage.webSocketDebuggerUrl);
  let id = 1;
  const pending = new Map();

  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const msgId = id++;
      pending.set(msgId, { resolve, reject });
      ws.send(JSON.stringify({ id: msgId, method, params }));
    });
  }

  ws.onmessage = (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) {
      const p = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) p.reject(msg.error);
      else p.resolve(msg.result);
    }
  };

  await new Promise(r => ws.onopen = r);
  console.log("Connected to CDP!");

  await send("Runtime.enable");

  // Evaluate fetch http://127.0.0.1:8088/health
  const res = await send("Runtime.evaluate", {
    expression: "fetch(\"http://127.0.0.1:8088/health\").then(r => r.json())",
    awaitPromise: true,
    returnByValue: true
  });
  console.log("Fetch 127.0.0.1:8088/health result:", JSON.stringify(res.result.value, null, 2));

  // Check state of the app
  const appState = await send("Runtime.evaluate", {
    expression: "({ title: document.title, logText: document.getElementById(\"eventLog\") ? document.getElementById(\"eventLog\").innerText.slice(-500) : \"none\" })",
    returnByValue: true
  });
  console.log("App log snippet:\n", appState.result.value.logText);

  ws.close();
}
main().catch(console.error);
