async function main() {
  const pages = await fetch("http://192.168.1.15:9998/json").then(r => r.json());
  const pocPage = pages.find(p => p.url && p.url.includes("com.cinejoy.poc"));
  const ws = new WebSocket(pocPage.webSocketDebuggerUrl);
  let id = 1;
  const pending = new Map();
  function send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const msgId = id++;
      pending.set(msgId, { resolve, reject });
      ws.send(JSON.stringify({ id: msgId, method, params }));
    });
  }
  ws.onmessage = (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) {
      const p = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) p.reject(msg.error);
      else p.resolve(msg.result);
    }
  };
  await new Promise(r => ws.onopen = r);
  await send("Runtime.enable");

  const vInfo = await send("Runtime.evaluate", {
    expression: `(() => {
      const v = document.getElementById("poc-video");
      if (!v) return { error: "No video element" };
      let bufRanges = [];
      for (let i = 0; i < v.buffered.length; i++) {
        bufRanges.push({ start: v.buffered.start(i), end: v.buffered.end(i) });
      }
      return {
        src: v.src,
        currentTime: v.currentTime,
        duration: v.duration,
        paused: v.paused,
        ended: v.ended,
        readyState: v.readyState,
        networkState: v.networkState,
        buffered: bufRanges,
        videoWidth: v.videoWidth,
        videoHeight: v.videoHeight
      };
    })()`,
    returnByValue: true
  });
  console.log("Video status:", JSON.stringify(vInfo.result.value, null, 2));
  ws.close();
}
main().catch(console.error);
