        paused: v.paused,
        seeking: v.seeking,
        readyState: v.readyState,
        bufferedEnd: v.buffered.length > 0 ? v.buffered.end(v.buffered.length - 1) : 0
      };
    })()`,
    returnByValue: true
  });
  console.log("Current video info:", JSON.stringify(vInfo.result.value, null, 2));
  ws.close();
}
main().catch(console.error);
