"      let pages = await fetch(`http://${CONFIG.tvIp}:${CONFIG.devtoolsPort}/json`).then(r => r.json());
      let prodPage = pages.find(p => p.url && p.url.includes(CONFIG.prodAppId));
      if (!prodPage) {
        execSync(`ares-launch -d ${CONFIG.aresDevice} ${CONFIG.prodAppId}`);
        await sleep(2500);
        pages = await fetch(`http://${CONFIG.tvIp}:${CONFIG.devtoolsPort}/json`).then(r => r.json());
        prodPage = pages.find(p => p.url && p.url.includes(CONFIG.prodAppId));
      }
      if (!prodPage) throw new Error(`Production app (${CONFIG.prodAppId}) not found in running targets`);

      const prodCdp = new CdpClient(prodPage.webSocketDebuggerUrl);
      await prodCdp.connect();
      await prodCdp.send('Runtime.enable');

      const prodState = await prodCdp.evaluate(`({
        title: document.title,
        hash: window.location.hash,
        ready: document.readyState
      })`);

      prodCdp.close();

      if (!prodState.title.includes('Cinejoy')) {
        throw new Error(`Production app title mismatch: ${prodState.title}`);
      }

      // Verify production on-disk files are intact
      const prodFiles = execSsh(`ls -1 /media/developer/apps/usr/palm/applications/${CONFIG.prodAppId}`);
      if (!prodFiles.includes('appinfo.json') || !prodFiles.includes('index.html')) {
        throw new Error(`Production app files missing or corrupted: ${prodFiles}`);
      }

      // Restore PoC app to foreground
      execSync(`ares-launch -d ${CONFIG.aresDevice} ${CONFIG.appId}`);

      console.log(`     Production App Title: "${prodState.title}" | Hash: "${prodState.hash}" | Ready: ${prodState.ready}`);
      console.log(`     Production Files Verified: appinfo.json, index.html present and intact`);
      return prodState;"

